// O estado é a fonte da verdade; o display é função dele.
let segundosRestantes = 25 * 60;
let rodando = false;
let fase = 'foco';          // 'foco' | 'intervalo'

function mmss(s) {
  const m = String(Math.floor(s / 60)).padStart(2, '0');
  const seg = String(s % 60).padStart(2, '0');
  return m + ':' + seg;
}
console.log(mmss(segundosRestantes));  // "25:00"

let idTimer = null;

function iniciar() {
  if (idTimer !== null) return;        // já está rodando: não empilha outro
  idTimer = setInterval(tick, 1000);
  rodando = true;
}
function pausar() {
  clearInterval(idTimer);              // para a contagem
  idTimer = null;
  rodando = false;
}
function tick() {
  segundosRestantes -= 1;
  if (segundosRestantes <= 0) pausar();
}

const DUR = { foco: 25 * 60, intervalo: 5 * 60 };

function aoZerar() {
  fase = (fase === 'foco') ? 'intervalo' : 'foco';   // alterna
  segundosRestantes = DUR[fase];                      // recarrega
  if (Notification.permission === 'granted') {
    new Notification(fase === 'foco' ? 'Hora de focar!' : 'Hora da pausa!');
  }
}
